    <div class="result-box">Batas belanja harian yang aman: <span class="big">${fmt(Math.max(0, (remaining() - state.bills.filter((b) => !b.paid).reduce((s, b) => s + b.amount, 0)) / (DAYS_IN_MONTH - DAY_OF_MONTH)))}</span> per hari.</div>
